import * as React from "react";
import { cx } from "./cx";

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Solid ink primary or hairline ghost. One primary per view. */
  variant?: "primary" | "ghost";
  size?: "default" | "sm";
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(function Button(
  { variant = "primary", size = "default", type = "button", className, ...props },
  ref,
) {
  return (
    <button
      ref={ref}
      type={type}
      className={cx(
        variant === "ghost" ? "rs-btn-ghost" : "rs-btn-primary",
        size === "sm" && "rs-btn-sm",
        className,
      )}
      {...props}
    />
  );
});

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Buttons ── */
.rs-btn-primary{font-family:inherit;font-size:14px;font-weight:600;letter-spacing:-.01em;display:inline-flex;align-items:center;justify-content:center;gap:8px;height:40px;padding:0 22px;background:var(--text);color:var(--bg);border:1px solid transparent;border-radius:var(--radius-sm);cursor:pointer;transition:opacity var(--duration-snap) var(--ease)}
.rs-btn-primary:hover{opacity:.85}
.rs-btn-primary:disabled{opacity:.4;cursor:not-allowed}
.rs-btn-ghost{font-family:inherit;font-size:14px;font-weight:500;letter-spacing:-.01em;display:inline-flex;align-items:center;justify-content:center;gap:8px;height:40px;padding:0 22px;background:transparent;color:var(--text);border:1px solid var(--divider);border-radius:var(--radius-sm);cursor:pointer;transition:background-color var(--duration-snap) var(--ease),color var(--duration-snap) var(--ease)}
.rs-btn-ghost:hover{background:var(--divider);border-color:transparent}
.rs-btn-ghost:disabled{opacity:.4;cursor:not-allowed;background:transparent;border-color:var(--divider)}
.rs-btn-primary:focus-visible,.rs-btn-ghost:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.rs-btn-sm{height:36px;padding:0 14px;font-size:13px;min-width:104px}
